/* @lc app=leetcode id=3835 lang=kotlin */ class Solution { fun countSubarrays(nums: IntArray, k: Long): Long = java.util.ArrayDeque<Int>().let { mx -> java.util.ArrayDeque<Int>().let { mn -> nums.indices.fold(0 to 0L) { (l, ans), r -> generateSequence { mx.peekLast()?.takeIf { nums[it] <= nums[r] } }.forEach { _ -> mx.pollLast() }.let { mx.addLast(r) }.let { generateSequence { mn.peekLast()?.takeIf { nums[it] >= nums[r] } }.forEach { _ -> mn.pollLast() } }.let { mn.addLast(r) }.let { generateSequence(l) { ll -> if ((nums[mx.peekFirst()] - nums[mn.peekFirst()]).toLong() * (r - ll + 1) > k) (ll + 1).also { nl -> (if (mx.peekFirst() < nl) mx.pollFirst() else null).let { if (mn.peekFirst() < nl) mn.pollFirst() } } else null }.last() }.let { l2 -> l2 to ans + (r - l2 + 1) } }.second } } }